#include <iostream>

int main()
{
    int number1 = 0;
    int number2 = 0;

    if (std::cin >> number1 >> number2)
    {
        try
        {
            if (number2 == 0)
            {
                throw number1;
            }
            std::cout << number1 << " / " << number2 << " is "
                      << (number1 / number2) << "\n";
        }
        catch (int ex)
        {
            std::cout << "Exception: an integer " << ex
                      << " cannot be divided by zero\n";
        }

        std::cout << "Execution continues ...\n";
    }

    return 0;
}
